CREATE FUNCTION public.library_quarter(t timestamptz) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT to_char(t AT TIME ZONE 'UTC','YYYY')||'Q'||extract(quarter FROM t AT TIME ZONE 'UTC')::int; $$;
CREATE FUNCTION public.library_archive_state() RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ WITH archives AS (SELECT domain,jsonb_agg(jsonb_build_object('captured_at',captured_at,'quarter',signals#>>'{archive,quarter}') ORDER BY captured_at,id) wayback FROM public.library_snapshots WHERE source='wayback' AND page_type='home' AND viewport='desktop' GROUP BY domain) SELECT jsonb_build_object('sites',coalesce(jsonb_agg(jsonb_build_object('domain',s.domain,'wayback',coalesce(a.wayback,'[]'::jsonb)) ORDER BY s.domain),'[]'::jsonb)) FROM public.library_sites s LEFT JOIN archives a USING(domain) WHERE s.active=true; $$;
CREATE FUNCTION public.library_archive_store(p_snapshot jsonb) RETURNS integer LANGUAGE plpgsql SET search_path='' AS $$ DECLARE n integer; BEGIN IF p_snapshot->>'source'<>'wayback' OR p_snapshot->>'page_type'<>'home' OR p_snapshot->>'viewport'<>'desktop' THEN RAISE EXCEPTION 'Archive desktop home required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_snapshot->>'domain',0)); INSERT INTO public.library_snapshots(domain,page_type,viewport,source,captured_at,url,run_id,html_hash,content_hash,signals_hash,signals) VALUES(p_snapshot->>'domain','home','desktop','wayback',(p_snapshot->>'captured_at')::timestamptz,p_snapshot->>'url',p_snapshot->>'run_id',p_snapshot->>'html_hash',p_snapshot->>'content_hash',p_snapshot->>'signals_hash',p_snapshot->'signals') ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END; $$;
CREATE FUNCTION public.library_archive_input(p_domain text) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'domain',s.domain,'sector',l.sector,'page_type',s.page_type,'viewport',s.viewport,'source',s.source,'captured_at',s.captured_at,'signals',s.signals||jsonb_build_object('ai_tags',coalesce(t.tags,'{}'::jsonb))) ORDER BY s.captured_at,s.id),'[]'::jsonb) FROM public.library_snapshots s JOIN public.library_sites l USING(domain) LEFT JOIN public.library_tags t ON t.snapshot_id=s.id WHERE s.domain=p_domain AND s.source='wayback' AND s.page_type='home' AND s.viewport='desktop'; $$;
CREATE FUNCTION public.library_archive_replace(p_domain text,p_expected jsonb,p_history jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path='' AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_domain,0)); IF public.library_archive_input(p_domain) IS DISTINCT FROM p_expected THEN RETURN false; END IF; DELETE FROM public.library_events WHERE domain=p_domain AND source='wayback'; DELETE FROM public.library_baselines WHERE domain=p_domain AND source='wayback'; INSERT INTO public.library_baselines(domain,page_type,viewport,source,signals,snapshot_id,confirmed_at,pending) SELECT p_domain,x->>'page_type',x->>'viewport','wayback',x#>'{baseline,signals}',(x#>>'{baseline,snapshot_id}')::bigint,(x#>>'{baseline,confirmed_at}')::timestamptz,x->'pending' FROM jsonb_array_elements(p_history->'baselines') x WHERE x->>'source'='wayback' AND x->>'domain'=p_domain; INSERT INTO public.library_events(domain,page_type,viewport,source,detected_at,effective_at,type,severity,summary,before,after,prev_snapshot_id,snapshot_id) SELECT p_domain,x->>'page_type',x->>'viewport','wayback',now(),(x->>'effective_at')::timestamptz,x->>'type',(x->>'severity')::smallint,x->>'summary',x->'before',x->'after',(x->>'prev_snapshot_id')::bigint,(x->>'snapshot_id')::bigint FROM jsonb_array_elements(p_history->'events') x WHERE x->>'source'='wayback' AND x->>'domain'=p_domain; RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.library_archive_state(),public.library_archive_store(jsonb),public.library_archive_input(text),public.library_archive_replace(text,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.library_archive_state(),public.library_archive_store(jsonb),public.library_archive_input(text),public.library_archive_replace(text,jsonb,jsonb) TO service_role;
CREATE OR REPLACE VIEW public.library_pending AS SELECT b.domain,b.page_type,b.viewport,p.key AS field,CASE WHEN p.key IN ('h1','body') THEN p.value#>'{from,family}' ELSE p.value->'from' END AS "from",CASE WHEN p.key IN ('h1','body') THEN p.value#>'{to,family}' ELSE p.value->'to' END AS "to",(p.value->>'first_seen_at')::timestamptz AS first_seen_at FROM public.library_baselines b CROSS JOIN LATERAL jsonb_each(b.pending) p WHERE b.source='live';